"""Exact-rational verification of the three-law ladder, the caps, and the scan-order criteria.

Every claim below is decided in exact rational arithmetic over a full grid, so the output is a
verification rather than an estimate:

  * the three fixed-window cost laws are in arithmetic progression with common gap mu(1-P);
  * the cap S_A <= 1/mu holds on the whole grid whenever mu <= 1/2 and fails only above it,
    the honest bound being 1/min(mu, 1-mu);
  * at mu = 1/2 the certified cost is 1/2 for every P;
  * block-first ordering is unconditionally optimal for the certified protocol, and optimal for
    the re-scan protocol exactly on the region mu <= P.
"""

from __future__ import annotations

from fractions import Fraction
from typing import List, Tuple

GRID = 24


def cost_cert(mu: Fraction, p: Fraction) -> Fraction:
    return mu * p + (1 - p) * (1 - mu)


def cost_fos(mu: Fraction, p: Fraction) -> Fraction:
    return 1 - (1 - mu) * p


def cost_rescan(mu: Fraction, p: Fraction) -> Fraction:
    return mu + (1 - p)


def cost_cert_comp(mu: Fraction, p: Fraction) -> Fraction:
    return p + (1 - p) * (1 - mu)


def cost_rescan_comp(mu: Fraction, p: Fraction) -> Fraction:
    return (1 - mu) + p


def main() -> None:
    ladder_ok = True
    cap_small_ok = True
    cap_honest_ok = True
    cap_violations: List[Tuple[Fraction, Fraction]] = []
    order_a_ok = True
    order_b_mismatch = 0

    for i in range(1, GRID):
        for j in range(0, GRID + 1):
            mu, p = Fraction(i, GRID), Fraction(j, GRID)
            a, b, c = cost_cert(mu, p), cost_fos(mu, p), cost_rescan(mu, p)

            ladder_ok &= (b - a == mu * (1 - p) == c - b)

            s = Fraction(1) / a
            if mu <= Fraction(1, 2):
                cap_small_ok &= (s <= Fraction(1) / mu)
            elif s > Fraction(1) / mu:
                cap_violations.append((mu, p))
            cap_honest_ok &= (s <= Fraction(1) / min(mu, 1 - mu))

            order_a_ok &= (a <= cost_cert_comp(mu, p))
            if (c <= cost_rescan_comp(mu, p)) != (mu <= p):
                order_b_mismatch += 1

    print("arithmetic progression, gap mu(1-P)      :", "HOLDS" if ladder_ok else "FAILS")
    print("cap S_A <= 1/mu on the regime mu <= 1/2  :", "HOLDS" if cap_small_ok else "FAILS")
    print("honest cap S_A <= 1/min(mu,1-mu)         :", "HOLDS" if cap_honest_ok else "FAILS")
    print("cells with mu > 1/2 breaking 1/mu        :", len(cap_violations))
    print("block-first optimal for protocol A       :", "ALWAYS" if order_a_ok else "NOT ALWAYS")
    print("cells where 'block-first iff mu <= P' fails for B:", order_b_mismatch)

    print("\nsharpness witness  (mu, P) = (9/10, 0):")
    mu, p = Fraction(9, 10), Fraction(0)
    print(f"    certified cost = {cost_cert(mu, p)},  S_A = {Fraction(1)/cost_cert(mu, p)}, "
          f"1/mu = {Fraction(1)/mu}")

    print("\nbalanced block mu = 1/2:")
    for j in range(0, 5):
        p = Fraction(j, 4)
        print(f"    P = {p}: certified cost = {cost_cert(Fraction(1,2), p)}")


if __name__ == "__main__":
    main()
